// Flatten the JSON:API campaign list into { id, name, send_time } items
const doc = $input.first().json;
const campaigns = (doc.data || []).map(c => ({
  id: c.id,
  name: c.attributes.name,
  send_time: c.attributes.send_time,
}));
return [{ json: { campaigns, ids: campaigns.map(c => c.id) } }];

// Join the three data sources, apply thresholds, build the Slack Block Kit message
const cfg = $('Config').first().json;
const lookbackDays = cfg.lookbackDays ?? 3;
const limits = {
  Hard: cfg.hardBounceThreshold ?? 0.005,
  Soft: cfg.softBounceThreshold ?? 0.02,
  Total: cfg.totalBounceThreshold ?? 0.02,
};
const { campaigns } = $('Extract Campaigns').first().json;
const statRows = $('Delivery Stats').first().json.data.attributes.results;
const splitRows = $('Hard-Soft Bounce Split').first().json.data.attributes.results;

const stats = {};
for (const row of statRows) stats[row.groupings.campaign_id] = row.statistics;
const split = {};
for (const row of splitRows) {
  const [cid, btype] = row.dimensions;
  split[cid] = split[cid] || { hard: 0, soft: 0 };
  split[cid][btype.toLowerCase().includes('hard') ? 'hard' : 'soft'] += row.measurements.count[0];
}

const pct = (x) => (x * 100).toFixed(2) + '%';
const results = campaigns.map(c => {
  const st = stats[c.id] || {};
  const sp = split[c.id] || { hard: 0, soft: 0 };
  const recipients = st.recipients || 1;
  const rates = {
    Hard: sp.hard / recipients,
    Soft: sp.soft / recipients,
    Total: st.bounce_rate ?? (sp.hard + sp.soft) / recipients,
  };
  const breaches = ['Hard', 'Soft', 'Total']
    .filter(k => rates[k] > limits[k])
    .map(k => [k, rates[k], limits[k]]);
  return { ...c, recipients: st.recipients || 0, delivered: st.delivered || 0,
           rates, totalRate: rates.Total, breaches,
           severity: breaches.some(b => b[0] === 'Hard') ? 'red' : (breaches.length ? 'orange' : 'ok') };
});

const flagged = results.filter(r => r.breaches.length);
const healthy = results.filter(r => !r.breaches.length);
const icon = flagged.some(r => r.severity === 'red') ? '🚨' : (flagged.length ? '⚠️' : '✅');
const COLORS = { red: '#E01E5A', orange: '#ECB22E', green: '#2EB67D' };

const blocks = [];
blocks.push({ type: 'header', text: { type: 'plain_text', text: `${icon} Klaviyo Bounce Monitor` } });
blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text:
  `Last ${lookbackDays} days · *${results.length}* campaigns checked · *${flagged.length}* flagged · ${healthy.length} healthy` }] });

const field = (label, rate, breached, limit) => ({ type: 'mrkdwn',
  text: `*${label}*\n${breached ? '⚠️ ' : ''}${pct(rate)} · limit ${pct(limit)}` });

const attachments = [];
for (const r of flagged) {
  const breached = new Set(r.breaches.map(b => b[0]));
  const headline = r.severity === 'red' ? 'hard bounces elevated' : 'soft/total bounces elevated';
  attachments.push({
    color: COLORS[r.severity],
    blocks: [{
      type: 'section',
      text: { type: 'mrkdwn', text: `*${r.name}* — ${headline}\nSent ${(r.send_time || '').slice(0, 16).replace('T', ' ')} UTC` },
      fields: [
        field('Hard bounce', r.rates.Hard, breached.has('Hard'), limits.Hard),
        field('Soft bounce', r.rates.Soft, breached.has('Soft'), limits.Soft),
        field('Total bounce', r.rates.Total, breached.has('Total'), limits.Total),
        { type: 'mrkdwn', text: `*Delivered*\n${r.delivered.toLocaleString()} / ${r.recipients.toLocaleString()}` },
      ],
    }],
  });
}
if (healthy.length) {
  attachments.push({
    color: COLORS.green,
    blocks: [{ type: 'section', text: { type: 'mrkdwn', text:
      `*${healthy.length} healthy* · ` + healthy.map(r => `${r.name} (${pct(r.totalRate)})`).join(' · ') } }],
  });
}

return [{ json: { payload: { blocks, attachments }, flaggedCount: flagged.length } }];
